  { ...{"id":"travis","kind":"technique","title":"Travis picking","domain":"picking","level":[1,10],"summary":"An alternating thumb bass with the fingers between the beats: from the thumb alone, one finger and the pinch to pattern variations, walking bass, the muted thumb, hammer-ons and a melody on top, in every key with a capo.","aliases":["alternating bass fingerpicking","Travis-style fingerpicking"],"prereqs":[],"stages":[{"tier":"foundations","title":"The thumb, then the fingers","goal":"Play the alternating thumb through I–vi–IV–V for 8 bars at 90 BPM without a pause at the changes, find each chord’s two bass strings from memory, add one finger on the \"and\" of 2 and 4 and the pinch on beat 1, and play the basic pattern through a simple song progression at 70 BPM.","levels":[1,3],"skills":4,"lessons":9,"full":true},{"tier":"intermediate","title":"Variations, keys and the bass","goal":"Play the pattern with pinches on 1 and 3, every off-beat filled and the syncopated \"and of 2\" at 96 BPM, switch keys with a capo every block, walk the bass and mute the thumb, recall patterns by name, and accompany a ragtime and a country progression.","levels":[4,6],"skills":5,"lessons":10,"full":true},{"tier":"advanced","title":"Melody, hammer-ons, any key","goal":"Play a melody on the top string over the thumb, hammer-ons into the thumb’s beat, the pattern in four keys and minor keys from memory, and an 8-bar song accompaniment with an intro, at 100 BPM.","levels":[7,8],"skills":4,"lessons":8,"full":true},{"tier":"mastery","title":"Fluent, any key, your own","goal":"Play the full pattern with walking bass and the syncopated melody at 110 BPM, switch key, pattern and progression on demand, and perform your own 8-bar arrangement.","levels":[9,10],"skills":3,"lessons":6,"full":true}],"lessons":33,"complete":true,"deep":false,"taught":false,"taughtOn":null}, re: /travis(-| )?pick|travis (pattern|style)|alternating(-| )thumb|alternating bass fingerpick/ },
  { ...{"id":"vibrato","kind":"technique","title":"Vibrato","domain":"fretting","level":[1,10],"summary":"A vibrato that makes held notes sing, from the first slow pulse locked to the click to a width, speed and onset chosen on purpose: on every finger and string, on bends, double-stops and slides, in any key and in real solos.","aliases":["finger vibrato","wrist vibrato"],"prereqs":["pentatonic","bending"],"stages":[{"tier":"foundations","title":"A steady, in-tune pulse","goal":"Hold the ♭3, the 5th and the root of box 1 with a measured half-step vibrato at one cycle a beat at 60 BPM, then two cycles a beat, even and returning to pitch every time, with every finger, name the landing notes of the box from memory, and end two phrases on a singing note over a minor groove.","levels":[1,3],"skills":4,"lessons":8,"full":true},{"tier":"intermediate","title":"Width, speed and onset on purpose","goal":"Play measured vibrato at two, three and four cycles a beat and at half-step and whole-step width on demand at 70 BPM, delay the onset and widen a vibrato in time, hold vibrato at the top of a bend and on the bass strings, find the landing notes of all five boxes, and end every phrase of a slow solo with a deliberate vibrato.","levels":[4,6],"skills":5,"lessons":10,"full":true},{"tier":"advanced","title":"Vibrato as expression","goal":"Lock vibrato to triplets and 16ths at 80 BPM, hold a unison bend with vibrato, give double-stops and slide-in notes an even vibrato, find landing notes in four keys and any box from memory, and play a blues solo where every held note has the vibrato it needs.","levels":[7,8],"skills":4,"lessons":8,"full":true},{"tier":"mastery","title":"Your vibrato, at will","goal":"Play a wide, 16th-note vibrato at performance tempo without losing pitch, give any note in any key the called width, speed and onset on demand, and perform your own 8-bar vibrato piece.","levels":[9,10],"skills":3,"lessons":6,"full":true}],"lessons":32,"complete":true,"deep":false,"taught":false,"taughtOn":null}, re: /vibrato|singing (held )?notes|wide vibrato/ }
